<main class="main"><div class="main__inner"><div class="module-page"><section class="portal-identity-panel"><span class="portal-identity-panel__avatar"><?=e(strtoupper(substr($guardian['name'],0,1)))?></span><div class="portal-identity-panel__copy"><span class="portal-identity-panel__eyebrow">Parent workspace</span><h1><?=e($guardian['name'])?></h1><p><?=count($children)?> linked child<?=count($children)===1?'':'ren'?></p></div></section><section class="module-card"><header class="module-card__header"><div><h2>My Children</h2><p>Only students linked by the institute appear here.</p></div></header><div class="module-card__body"><div class="portal-document-grid"><?php foreach($children as$s):?><a class="portal-document" href="<?=url('/portal/parent/children/'.$s['id'])?>"><span class="portal-document__icon"><i data-lucide="graduation-cap"></i></span><span><strong><?=e($s['student_name'])?></strong><small><?=e($s['registration_no'].' · '.$s['class_name'])?></small></span><i data-lucide="chevron-right"></i></a><?php endforeach?><?php if(!$children):?><div class="compact-empty"><h3>No children linked</h3><p>Ask the institute administrator to link your child record.</p></div><?php endif?></div></div></section></div></div></main>
